 let runtime,live=false,speed=1;const nativeRaf=requestAnimationFrame.bind(window),nativeNow=performance.now.bind(performance);let dirty=false;const timing={last:null,acc:0};const box=document.getElementById('game');const scratch=document.createElement('canvas').getContext('2d');const overrides={};const context=new Proxy(overrides,{get:(o,k)=>{if(k in o)return o[k];const c=box.querySelector('canvas')?.getContext('2d')||scratch;return typeof c[k]==='function'?(...args)=>{const active=box.querySelector('canvas')?.getContext('2d')||scratch;return active[k](...args);}:c[k];},set:(o,k,v)=>{if(typeof v==='function')o[k]=v;else (box.querySelector('canvas')?.getContext('2d')||scratch)[k]=v;return true;}});
